// Purpose: ROW-027 and ROW-028 (REQ-014) — on the checker page, in every browser of the harness,
// text pasted with the browser's own paste keeps plain text only (no bold, link or colour), and its
// line breaks, blank lines, bullet characters, tabs and runs of spaces survive the paste and any
// number of checks, replacements and ignores exactly.
// Provenance: generated by tests/invariants/spanish-dictionary.ts (accentPopulation, dictionary-es
// 4.0.0 pinned by SHA-256) and the harness's fresh markers, with a fresh seed per run; the formatted
// source is this test's own HTML, copied from a scratch page with the browser's own copy command.
//
// Test argument
// ROW-027 promise: pasting formatted text from a word processor keeps plain text only (REQ-014
//   fail-if "pasting formatted text from a word processor keeps bold, links or colours"; A-019).
// ROW-027 wrong product: an editable box that accepts the clipboard's HTML as it comes — the offer
//   keeps the <b>, the <a href> and the red colour, and they travel on with it.
// ROW-027 given: the clipboard holding formatted HTML (a bold run around a fresh misspelling, a link,
//   a red-coloured fresh marker, an italic word), copied from another page with the browser's copy;
//   when: it is pasted into the empty box with Ctrl/Cmd+V and Revisar ortografía is pressed; then: the
//   box's text is exactly the source's plain text, no element in the box is a link, bold, italic or
//   red, and the misspelling inside the former bold run is highlighted at its place — and before the
//   paste the box was empty.
// ROW-027 controls: the clipboard probe pasting the same copy into a rich area receives formatting —
//   the harmful input really is on the clipboard in this engine; untouched by the product.
// ROW-027 technique: a real copy and paste through the engine (never `fill`), a fresh marker so the
//   text is unique per run, the formatting looked for on the box's own elements.
// cases: ROW-027 target=ROW-027-pasted-formatted-text-keeps-plain-text-only control=ROW-027-control-the-clipboard-carries-formatting
//
// ROW-028 promise: line breaks, blank lines, bullet characters, tabs and runs of spaces survive paste
//   and any number of checks, replacements and ignores exactly (REQ-014 fail-if "any line break,
//   blank line, bullet character or space of the pasted text is added, removed or changed by pasting
//   or checking"; A-019).
// ROW-028 wrong product: a page that rebuilds the text from its words after a Replace (joining with
//   single spaces), collapses whitespace when drawing highlights into an editable box, or turns a tab
//   or a "•" into something else.
// ROW-028 given: a plain offer with "•" and "-" bullets, a tab, runs of 3 and 4 spaces, trailing
//   spaces, blank lines and a final line break, holding two fresh misspellings on different lines;
//   when: it is pasted with Ctrl/Cmd+V, checked, one misspelling replaced, the other ignored, and
//   checked again; then: after the paste and after every step the box's text is exactly the pasted
//   text with only the replaced word changed.
// ROW-028 controls: the clipboard probe carries the same layout text exactly — the source of the
//   paste is exact; untouched by the product.
// ROW-028 technique: whole-text comparison after every step, the expected text the test's own model
//   (the pasted text with the chosen suggestion at the place the test recorded).
// cases: ROW-028 target=ROW-028-line-breaks-bullets-tabs-and-spaces-survive-paste-checks-replace-and-ignore-exactly control=ROW-028-control-the-clipboard-carries-the-layout-exactly

import { expect, test } from '@playwright/test';
import { accentPopulation, asActor, el, freshMarker, freshRandom, openChecker, pressCheck, readHighlights, ROLES, type Placed, type Rng } from './harness';
import {
  chooseIgnore,
  chooseSuggestion,
  openMenuByPointer,
  pasteIntoOffer,
  putOnClipboard,
  putRichOnClipboard,
  readClipboard,
  readMenu,
  readOfferText,
  replacedAt,
  scratchPage,
} from './suggestions-helpers';

const WAIT_MS = 15_000;

function rich(rng: Rng) {
  const s = rng.pick(accentPopulation()).stripped;
  const marker = freshMarker();
  const html = `Buscamos <b>${s}</b> con <a href="https://ejemplo.example/oferta">experiencia</a> en <span style="color:#cc0000">${marker}</span> y <i>equipo</i>`;
  const plain = `Buscamos ${s} con experiencia en ${marker} y equipo`;
  return { s, html, plain, sAt: { start: 9, end: 9 + s.length, word: s } as Placed };
}

test('ROW-027-pasted-formatted-text-keeps-plain-text-only', async ({ page, context }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const r = rich(rng);
  const scratch = await scratchPage(context);
  await openChecker(page);
  expect(await readOfferText(page), 'ROW-027: before the paste the box is empty').toBe('');

  await putRichOnClipboard(scratch, r.html);
  await pasteIntoOffer(page);
  await expect.poll(() => readOfferText(page), { message: `ROW-027: the box holds exactly the source's plain text (seed ${rng.seed})`, timeout: WAIT_MS }).toBe(r.plain);

  const formatting = await el(page, ROLES.offer)
    .first()
    .evaluate((box) => {
      const boxStyle = getComputedStyle(box);
      const found: string[] = [];
      for (const n of Array.from(box.querySelectorAll('*'))) {
        const e = n as HTMLElement;
        const tag = e.tagName.toLowerCase();
        const cs = getComputedStyle(e);
        if (tag === 'a' || e.hasAttribute('href')) found.push(`link <${tag}>`);
        if (['b', 'strong', 'i', 'em', 'font', 'u'].includes(tag)) found.push(`<${tag}>`);
        if (e.getAttribute('data-element') === 'flag') continue; // the product's own highlight is drawn apart by design
        if (cs.color === 'rgb(204, 0, 0)') found.push(`red <${tag}>`);
        if (Number(cs.fontWeight) >= 600 && Number(cs.fontWeight) > Number(boxStyle.fontWeight)) found.push(`bold <${tag}>`);
        if (cs.fontStyle === 'italic' && boxStyle.fontStyle !== 'italic') found.push(`italic <${tag}>`);
      }
      return found;
    });
  expect(formatting, 'ROW-027: no link, bold, italic or colour from the pasted source is in the box').toEqual([]);

  expect((await pressCheck(page)).status, 'ROW-027: the check of the pasted text is answered').toBe(200);
  await expect
    .poll(async () => (await readHighlights(page, r.plain)).map((h) => `${h.word}@${h.start}`), { message: `ROW-027: the misspelling from the bold run is highlighted at its place in the plain text (seed ${rng.seed})`, timeout: WAIT_MS })
    .toEqual([`${r.s}@${r.sAt.start}`]);
  expect(await readOfferText(page), 'ROW-027: the check leaves the plain text exactly as pasted').toBe(r.plain);
});

test('ROW-027-control-the-clipboard-carries-formatting', async ({ context }) => {
  asActor('anonymous');
  const r = rich(freshRandom());
  const scratch = await scratchPage(context);
  await putRichOnClipboard(scratch, r.html);
  const got = await readClipboard(scratch);
  expect(got.richFormatted, `ROW-027 control: the copied source carries its formatting on the clipboard — ${got.richHtml}`).toBe(true);
});

function layout(rng: Rng) {
  const pop = accentPopulation();
  const a = rng.pick(pop);
  let b = rng.pick(pop);
  while (b.word === a.word || b.stripped.includes(a.stripped) || a.stripped.includes(b.stripped)) b = rng.pick(pop);
  const lines = [
    'OFERTA DE EMPLEO   ',
    '',
    `Buscamos persona para ${a.stripped} del equipo.`,
    '',
    '',
    'Requisitos:',
    '•  experiencia en proyectos',
    `-\tformación ${'    '}completa`,
    `   • trabajo con ${b.stripped} y clientes  `,
    '',
    'Ofrecemos:\tcontrato    y salario',
    '',
  ];
  const text = lines.join('\n');
  const at = (w: string): Placed => {
    const start = text.indexOf(` ${w} `) + 1;
    return { start, end: start + w.length, word: w };
  };
  return { text, pA: at(a.stripped), pB: at(b.stripped) };
}

test('ROW-028-line-breaks-bullets-tabs-and-spaces-survive-paste-checks-replace-and-ignore-exactly', async ({ page, context }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const { text, pA, pB } = layout(rng);
  const scratch = await scratchPage(context);
  await openChecker(page);
  await putOnClipboard(scratch, text);
  await pasteIntoOffer(page);
  await expect.poll(() => readOfferText(page), { message: 'ROW-028: the paste keeps every line break, blank line, bullet, tab and space', timeout: WAIT_MS }).toBe(text);

  expect((await pressCheck(page)).status, 'ROW-028: the first check is answered').toBe(200);
  await expect
    .poll(async () => (await readHighlights(page, text)).map((h) => `${h.word}@${h.start}`), { message: `ROW-028: both misspellings are highlighted (seed ${rng.seed})`, timeout: WAIT_MS })
    .toEqual([`${pA.word}@${pA.start}`, `${pB.word}@${pB.start}`]);
  expect(await readOfferText(page), 'ROW-028: the check leaves the text exactly as pasted').toBe(text);

  await openMenuByPointer(page, text, pA.start, 'ROW-028');
  const label = (await readMenu(page)).suggestions[0];
  expect(label, `ROW-028: "${pA.word}"'s menu holds a suggestion`).toBeTruthy();
  await chooseSuggestion(page, label, 'ROW-028');
  const replaced = replacedAt(text, pA, label);
  await expect.poll(() => readOfferText(page), { message: `ROW-028: after Replace only "${pA.word}" changed (seed ${rng.seed})`, timeout: WAIT_MS }).toBe(replaced);

  await openMenuByPointer(page, replaced, pB.start + (label.length - pA.word.length), 'ROW-028');
  await chooseIgnore(page, 'ROW-028');
  await expect.poll(async () => (await readHighlights(page, replaced)).length, { message: 'ROW-028: after Ignore no highlight remains', timeout: WAIT_MS }).toBe(0);
  expect(await readOfferText(page), 'ROW-028: after Ignore the text is unchanged').toBe(replaced);

  expect((await pressCheck(page)).status, 'ROW-028: the second check is answered').toBe(200);
  await expect
    .poll(async () => (await readHighlights(page, replaced)).map((h) => h.word), { message: 'ROW-028: the second check flags the ignored word again', timeout: WAIT_MS })
    .toEqual([pB.word]);
  expect(await readOfferText(page), 'ROW-028: after the second check the text is still exactly the pasted text with only the replaced word changed').toBe(replaced);
});

test('ROW-028-control-the-clipboard-carries-the-layout-exactly', async ({ context }) => {
  asActor('anonymous');
  const { text } = layout(freshRandom());
  const scratch = await scratchPage(context);
  await putOnClipboard(scratch, text);
  expect((await readClipboard(scratch)).text, 'ROW-028 control: the clipboard carries the layout text exactly').toBe(text);
});
